const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions (approximate polygon for Wuhan Jianghan District)
  const jianghan = ee.Geometry.Polygon([
    [[114.195, 30.55], [114.195, 30.66], [114.335, 30.66], [114.335, 30.55], [114.195, 30.55]]
  ]);
  const janStart = '2020-01-01';
  const janEnd = '2020-02-01';   // proxy for Jan 19 using monthly Jan
  const febStart = '2020-02-01';
  const febEnd = '2020-03-01';   // proxy for Feb 4 using monthly Feb

  const datasets = [
    // Prefer straylight-corrected monthly product
    {id: 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG', band: 'avg_rad', cfBand: 'cf_cvg'},
    // Fallback monthly product
    {id: 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG', band: 'avg_rad', cfBand: 'cf_cvg'}
  ];

  async function getMonthlyImage(start, end, geom) {
    for (const ds of datasets) {
      try {
        const col = ee.ImageCollection(ds.id).filterDate(start, end).filterBounds(geom);
        const size = await col.size().getInfo();
        if (size > 0) {
          const img = ee.Image(col.first()).select(ds.band);
          return {img: ee.Image(col.first()), band: ds.band, cfBand: ds.cfBand, dsid: ds.id, size: size};
        }
      } catch (e) {
        // try next dataset
      }
    }
    return null;
  }

  async function statsFor(imgObj, geom) {
    const {img, band, cfBand, dsid, size} = imgObj;
    const scale = 1000;
    const maxPixels = 1e9;

    // Count valid pixels for the band
    const countDict = await img.select(band).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: maxPixels
    }).getInfo();

    const count = countDict ? countDict[band] : 0;

    // Mean radiance
    const meanDict = await img.select(band).reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: scale,
      maxPixels: maxPixels
    }).getInfo();

    const meanVal = meanDict ? meanDict[band] : null;

    // Cloud-free coverage (if available)
    let cfMean = null;
    try {
      const hasCf = await img.bandNames().contains(cfBand).getInfo();
      if (hasCf) {
        const cfDict = await img.select(cfBand).reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: geom,
          scale: scale,
          maxPixels: maxPixels
        }).getInfo();
        cfMean = cfDict ? cfDict[cfBand] : null;
      }
    } catch (e) {
      cfMean = null;
    }

    return {meanVal, count, cfMean, dsid, size};
  }

  try {
    const janImgObj = await getMonthlyImage(janStart, janEnd, jianghan);
    const febImgObj = await getMonthlyImage(febStart, febEnd, jianghan);

    if (!janImgObj || !febImgObj) {
      console.log('Monthly images found: Jan:', janImgObj ? janImgObj.size : 0, ' Feb:', febImgObj ? febImgObj.size : 0);
      console.log('C1');
      return;
    }

    const janStats = await statsFor(janImgObj, jianghan);
    const febStats = await statsFor(febImgObj, jianghan);

    // Print concise evidence
    console.log('Region: Jianghan (approx), Scale: 1000m');
    console.log(`Jan 2020 Images: ${janStats.size} [${janStats.dsid.split('/').pop()}]`);
    console.log(`Feb 2020 Images: ${febStats.size} [${febStats.dsid.split('/').pop()}]`);
    console.log(`Jan avg_rad: ${janStats.meanVal !== null ? janStats.meanVal.toFixed(3) : 'null'}, Pixels: ${janStats.count}, cf_cvg: ${janStats.cfMean !== null ? janStats.cfMean.toFixed(2) : 'NA'}`);
    console.log(`Feb avg_rad: ${febStats.meanVal !== null ? febStats.meanVal.toFixed(3) : 'null'}, Pixels: ${febStats.count}, cf_cvg: ${febStats.cfMean !== null ? febStats.cfMean.toFixed(2) : 'NA'}`);

    // Handle C2: No valid pixels after masking
    if ((janStats.count === 0) || (febStats.count === 0)) {
      console.log('C2');
      return;
    }

    // Handle C3: Calculation failure (null/NaN or out-of-range)
    const invalidJan = (janStats.meanVal === null) || !isFinite(janStats.meanVal) || (janStats.meanVal < 0) || (janStats.meanVal > 1000);
    const invalidFeb = (febStats.meanVal === null) || !isFinite(febStats.meanVal) || (febStats.meanVal < 0) || (febStats.meanVal > 1000);
    if (invalidJan || invalidFeb) {
      console.log('C3');
      return;
    }

    const delta = febStats.meanVal - janStats.meanVal;
    console.log(`Delta (Feb - Jan): ${delta.toFixed(3)}`);

    // Final Answer: lower on Feb 4 (proxied by Feb monthly) compared to Jan 19 (proxied by Jan monthly)?
    if (febStats.meanVal < janStats.meanVal) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    // Any unexpected issue (e.g., band names, memory, API errors)
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
